import com.cricscore.scorelive.ui.theme.DarkBackground
import com.cricscore.scorelive.ui.theme.RadialTeal
import com.cricscore.scorelive.ui.theme.TextGray
import kotlinx.coroutines.delay

// Data class for Commentary from API
data class CommentaryEntry(
    val ballResult: String,
    val title: String,
    val over: String,
    val description: String,
    val color: Color,
)

// Data class for Player from API
data class Player(
    val name: String,
    val imageUrl: String = "", // Placeholder for coil or other image loading
)

@Composable
fun MatchDetailsScreen(matchName: String?, onBackClick: () -> Unit) {
    var selectedTabIndex by remember { mutableStateOf(0) } // Summary selected by default for now
    val tabs = listOf("Summery", "Scorecard", "Commentry")

    // Simulate API state
    val matchInfoState = remember { mutableStateOf<MatchInfo?>(null) }

    // Get sample scorecard data
    val (innings1, innings2) = remember { getSampleInningsData() }

    LaunchedEffect(Unit) {
        // Simulate API delay
        delay(1000)
        matchInfoState.value = MatchInfo(
            team1Short = "CSK",
            team1Full = "Chennai Super Kings",
            team2Short = "RCB",
            team2Full = "Royal Challengers Bengaluru",
            date = "Mar 22, 08:00 PM",
            venue = "MA Chidambaram Stadium, Chennai",
            toss = "Royal Challengers Bengaluru (Batting)",
            umpire = "Saidharsan Veetil",
            tvUmpire = "Bruce Oxenford",
            matchReferee = "Manu Nayyar"
        )
    }

    // Mock API Data for Commentary
    val commentaryList = remember {
        listOf(
            CommentaryEntry(
                "W",
                "OUT! Hardik Pandya c Smith b Starc",
                "18.2",
                "Full Toss, outside off stump on the front foot Slog, well timed in the air under control past deep mid wicket for 6 runs.",
                Color(0xFFE74C3C)
            ),
            CommentaryEntry(
                "6",
                "Hardik Pandya hits a SIX!",
                "18.1",
                "Full Toss, outside off stump on the front foot Slog, well timed in the air under control past deep mid wicket for 6 runs.",
                Color(0xFF8E44AD)
            ),
            CommentaryEntry(
                "4",
                "Hardik Pandya hits a FOUR!",
                "17.6",
                "Full Toss, outside off stump on the front foot Slog, well timed in the air under control past deep mid wicket for 6 runs.",
                Color(0xFFE67E22)
            ),
            CommentaryEntry(
                "6",
                "Hardik Pandya hits a SIX!",
                "17.5",
                "Full Toss, outside off stump on the front foot Slog, well timed in the air under control past deep mid wicket for 6 runs.",
                Color(0xFF8E44AD)
            ),
            CommentaryEntry(
                "4",
                "Hardik Pandya hits a FOUR!",
                "17.4",
                "Full Toss, outside off stump on the front foot Slog, well timed in the air under control past deep mid wicket for 6 runs.",
                Color(0xFFE67E22)
            ),
            CommentaryEntry(
                "6",
                "Hardik Pandya hits a SIX!",
                "17.3",
                "Full Toss, outside off stump on the front foot Slog, well timed in the air under control past deep mid wicket for 6 runs.",
                Color(0xFF8E44AD)
            )
        )
    }

    // Mock API Data for Squads
    val indiaPlayers = remember { List(11) { Player("R Sharma") } }
    val nzPlayers = remember { List(11) { Player("R Sharma") } }

    val radialGradient = Brush.radialGradient(
        colors = listOf(RadialTeal.copy(alpha = 0.5f), Color.Transparent),
        center = Offset(540f, -50f),
        radius = 1000f
    )

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(DarkBackground)
    ) {
        // Background Radial Gradient
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(350.dp)
                .background(radialGradient)
        )

        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
                .pointerInput(Unit) {
                    var totalDrag = 0f
                    detectHorizontalDragGestures(
                        onDragStart = { totalDrag = 0f },
                        onHorizontalDrag = { change, dragAmount ->
                            change.consume()
                            totalDrag += dragAmount
                        },
                        onDragEnd = {
                            if (totalDrag > 100) { // Swipe Right
                                if (selectedTabIndex > 0) selectedTabIndex--
                            } else if (totalDrag < -100) { // Swipe Left
                                if (selectedTabIndex < 2) selectedTabIndex++
                            }
                        }
                    )
                },
            contentPadding = PaddingValues(bottom = 24.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Header Section
            item {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 12.dp, bottom = 12.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text(
                        text = matchName ?: "IND vs AUS • 2nd T20I",
                        color = Color.White,
                        fontSize = 20.sp,
                        fontFamily = GilroyFontFamily,
                        fontWeight = FontWeight.Bold
                    )
                    Text(
                        text = "Live from Wankhede",
                        color = TextGray,
                        fontSize = 12.sp,
                        fontFamily = GilroyFontFamily,
                        fontWeight = FontWeight.Normal
                    )
                }
            }

            // Detail Score Card
            item {
                Box(modifier = Modifier.padding(horizontal = 16.dp)) {
                    DetailScoreCard()
                }
            }

            item { Spacer(modifier = Modifier.height(12.dp)) }

            // Player Performance Card
            item {
                Box(modifier = Modifier.padding(horizontal = 16.dp)) {
                    PlayerPerformanceCard()
                }
            }

            item { Spacer(modifier = Modifier.height(8.dp)) }

            // Recent Over Stats
            item {
                RecentOverStats()
            }

            // Tabs below the over screen
            item {
                DetailTabs(tabs, selectedTabIndex) { selectedTabIndex = it }
            }

            // Conditional Content based on selected tab with animation
            item {
                AnimatedContent(
                    targetState = selectedTabIndex,
                    transitionSpec = {
                        if (targetState > initialState) {
                            // Swiping left - content slides in from right
                            slideInHorizontally { width -> width } + fadeIn() togetherWith
                                    slideOutHorizontally { width -> -width } + fadeOut()
                        } else {
                            // Swiping right - content slides in from left
                            slideInHorizontally { width -> -width } + fadeIn() togetherWith
                                    slideOutHorizontally { width -> width } + fadeOut()
                        }
                    },
                    label = "TabContentTransition"
                ) { targetTabIndex ->
                    Column(modifier = Modifier.fillMaxWidth()) {
                        when (targetTabIndex) {
                            0 -> { // Summery (Squad View)
                                SquadView("Team India Squad", indiaPlayers)
                                Spacer(modifier = Modifier.height(24.dp))
                                SquadView("Team New Zealand Squad", nzPlayers)
                                Spacer(modifier = Modifier.height(24.dp))
                                MatchInfoTable(matchInfoState.value)
                                Spacer(modifier = Modifier.height(24.dp))
                            }
                            1 -> { // Scorecard
                                ScorecardScreen(innings1, innings2)
                            }
                            2 -> { // Commentry
                                Text(
                                    text = "Ball by Ball",
                                    color = Color.White,
                                    fontSize = 18.sp,
                                    fontFamily = GilroyFontFamily,
                                    fontWeight = FontWeight.Bold,
                                    modifier = Modifier.padding(start = 24.dp, top = 16.dp, bottom = 12.dp)
                                )
                                commentaryList.forEach { entry ->
                                    CommentaryItem(entry)
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun DetailScoreCard() {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .border(2.dp, Color(0xFF2C2C2E), RoundedCornerShape(28.dp)),
        colors = CardDefaults.cardColors(containerColor = CardBackground),
        shape = RoundedCornerShape(28.dp)
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            Column(modifier = Modifier.padding(20.dp)) {
                Text(
                    "Indian Premiere League",
                    color = TextGray,
                    fontSize = 14.sp,
                    fontFamily = GilroyFontFamily,
                    fontWeight = FontWeight.Normal,
                    modifier = Modifier.padding(bottom = 16.dp)
                )

                ScoreRowDetail("Mumbai Indians", "182/4", "(20)")
                Spacer(modifier = Modifier.height(16.dp))
                ScoreRowDetail("Australia", "52/4", "(12.2)")

                Spacer(modifier = Modifier.height(20.dp))

                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(1.dp)
                        .background(
                            brush = Brush.horizontalGradient(
                                colors = listOf(
                                    Color.Transparent,
                                    Color.White.copy(alpha = 0.2f),
                                    Color.White.copy(alpha = 0.2f),
                                    Color.Transparent
                                )
                            )
                        )
                )

                Spacer(modifier = Modifier.height(12.dp))

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Text(
                        "CRR : 5.24",
                        color = Color.White,
                        fontSize = 12.sp,
                        fontFamily = GilroyFontFamily
                    )
                    Text(
                        "RRR : 8.54",
                        color = Color.White,
                        fontSize = 12.sp,
                        fontFamily = GilroyFontFamily
                    )
                }
                Spacer(modifier = Modifier.height(12.dp))
            }

            Surface(
                modifier = Modifier.align(Alignment.BottomCenter),
                color = Color(0xFF2C2C2E),
                shape = RoundedCornerShape(topStart = 12.dp, topEnd = 12.dp)
            ) {
                Text(
                    "BAN need 189 runs in 135 balls",
                    color = Color.White.copy(alpha = 0.9f),
                    fontSize = 12.sp,
                    fontFamily = GilroyFontFamily,
                    modifier = Modifier.padding(horizontal = 24.dp, vertical = 6.dp)
                )
            }
        }
    }
}

@Composable
fun TeamFlagPlaceholder() {
    Box(
        modifier = Modifier
            .size(32.dp)
            .clip(CircleShape)
            .background(Color.Gray.copy(alpha = 0.2f))
            .border(1.dp, Color.White.copy(alpha = 0.1f), CircleShape)
    )
}

@Composable
fun ScoreRowDetail(name: String, score: String, overs: String) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            TeamFlagPlaceholder()
            Spacer(modifier = Modifier.width(12.dp))
            Text(
                text = name,
                color = Color.White,
                fontSize = 16.sp,
                fontFamily = GilroyFontFamily,
                fontWeight = FontWeight.Medium
            )
        }
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                text = score,
                color = Color.White,
                fontSize = 24.sp,
                fontFamily = GilroyFontFamily,
                fontWeight = FontWeight.Bold
            )
            Spacer(modifier = Modifier.width(6.dp))
            Text(
                text = overs,
                color = TextGray,
                fontFamily = GilroyFontFamily,
                fontSize = 14.sp
            )
        }
    }
}

@Composable
fun PlayerPerformanceCard() {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .border(2.dp, Color(0xFF2C2C2E), RoundedCornerShape(28.dp)),
        colors = CardDefaults.cardColors(containerColor = CardBackground),
        shape = RoundedCornerShape(28.dp)
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            Column(modifier = Modifier.padding(top = 20.dp, bottom = 40.dp)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceEvenly
                ) {
                    PlayerInfo("R Sharma", "24", "(8)", true)
                    Box(
                        modifier = Modifier
                            .width(1.dp)
                            .height(80.dp)
                            .background(Color.White.copy(0.1f))
                    )
                    PlayerInfo("S Yadav", "32", "(15)", false)
                    Box(
                        modifier = Modifier
                            .width(1.dp)
                            .height(80.dp)
                            .background(Color.White.copy(0.1f))
                    )
                    PlayerInfo("H Rauf", "0-32", "(2.5)", false, isBowler = true)
                }
            }

            Surface(
                modifier = Modifier.align(Alignment.BottomCenter),
                color = Color(0xFF2C2C2E),
                shape = RoundedCornerShape(topStart = 12.dp, topEnd = 12.dp)
            ) {
                Text(
                    "P'ship : 1(2) | Last Wkt : Litton Das 41(33)",
                    color = Color.White.copy(alpha = 0.9f),
                    fontSize = 11.sp,
                    fontFamily = GilroyFontFamily,
                    modifier = Modifier.padding(horizontal = 20.dp, vertical = 6.dp)
                )
            }
        }
    }
}

@Composable
fun PlayerInfo(
    name: String,
    score: String,
    detail: String,
    isOnStrike: Boolean,
    isBowler: Boolean = false,
) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        Box {
            Box(
                modifier = Modifier
                    .size(70.dp)
                    .clip(CircleShape)
                    .background(Color.Gray.copy(0.2f))
            )
            if (isOnStrike) {
                Text(
                    text = "",
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .offset(x = 6.dp, y = (-4).dp),
                    fontSize = 18.sp
                )
            }
        }
        Spacer(modifier = Modifier.height(8.dp))
        Text(
            name,
            color = Color.White,
            fontSize = 14.sp,
            fontWeight = FontWeight.Bold,
            fontFamily = GilroyFontFamily
        )
        Row {
            Text(
                score,
                color = Color.White,
                fontSize = 12.sp,
                fontWeight = FontWeight.Bold,
                fontFamily = GilroyFontFamily
            )
            Spacer(modifier = Modifier.width(4.dp))
            Text(detail, color = TextGray, fontSize = 10.sp, fontFamily = GilroyFontFamily)
        }
    }
}

@Composable
fun RecentOverStats() {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .horizontalScroll(rememberScrollState())
            .padding(horizontal = 16.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Text("= 17 | Over 14", color = Color.White, fontSize = 14.sp, fontFamily = GilroyFontFamily)
        BallStat("4", Color(0xFFE67E22))
        BallStat("4", Color(0xFFE67E22))
        BallStat("6", Color(0xFF8E44AD))
        BallStat("W", Color(0xFFE74C3C))
        BallStat("wd", Color(0xFF2C3E50))
        BallStat("0", Color(0xFF2C3E50))
        BallStat("B2", Color(0xFF2C3E50))
        Text("= 17", color = Color.White, fontSize = 14.sp, fontFamily = GilroyFontFamily)
    }
}

@Composable
fun BallStat(text: String, color: Color) {
    Box(
        modifier = Modifier
            .size(28.dp)
            .clip(CircleShape)
            .background(color),
        contentAlignment = Alignment.Center
    ) {
        Text(text, color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
    }
}

@Composable
fun DetailTabs(tabs: List<String>, selectedIndex: Int, onTabSelected: (Int) -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = 16.dp, bottom = 8.dp),
        horizontalArrangement = Arrangement.SpaceAround,
        verticalAlignment = Alignment.CenterVertically
    ) {
        tabs.forEachIndexed { index, title ->
            val isSelected = selectedIndex == index
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                modifier = Modifier
                    .clickable { onTabSelected(index) }
                    .padding(horizontal = 12.dp)
            ) {
                Text(
                    text = title,
                    color = if (isSelected) Color(0xFF00BFA5) else Color.White,
                    fontSize = 16.sp,
                    fontFamily = GilroyFontFamily,
                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal
                )
                if (isSelected) {
                    Spacer(modifier = Modifier.height(6.dp))
                    Box(
                        modifier = Modifier
                            .width(60.dp)
                            .height(2.5.dp)
                            .background(Color(0xFF00BFA5), RoundedCornerShape(2.dp))
                    )
                } else {
                    Spacer(modifier = Modifier.height(8.5.dp))
                }
            }
        }
    }
}

@Composable
fun MatchInfoTable(matchInfo: MatchInfo?) {
    if (matchInfo == null) return

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp)
            .background(Color(0xFF232325), RoundedCornerShape(8.dp))
    ) {
        Text(
            "Match Information",
            color = Color.White,
            fontWeight = FontWeight.Bold,
            fontSize = 15.sp,
            modifier = Modifier
                .fillMaxWidth()
                .background(Color(0xFF3A3A3C), RoundedCornerShape(topStart = 8.dp, topEnd = 8.dp))
                .padding(vertical = 8.dp, horizontal = 12.dp)
        )
        InfoRow(matchInfo.team1Short, matchInfo.team1Full)
        InfoRow(matchInfo.team2Short, matchInfo.team2Full)
        InfoRow("Date", matchInfo.date)
        InfoRow("Venue", matchInfo.venue)
        InfoRow("Toss", matchInfo.toss)
        InfoRow("Umpire", matchInfo.umpire)
        InfoRow("TV Umpire", matchInfo.tvUmpire)
        InfoRow("Match Referee", matchInfo.matchReferee)
    }
}

@Composable
fun InfoRow(label: String, value: String) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .background(Color.Black)
            .padding(horizontal = 12.dp, vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Text(label, color = Color.White, fontWeight = FontWeight.Bold, fontSize = 14.sp)
        Text(value, color = Color.White, fontSize = 14.sp)
    }
    HorizontalDivider(
        thickness = 0.5.dp,
        color = Color.White.copy(alpha = 0.1f),
    )
}

@Composable
fun SquadView(title: String, players: List<Player>) {
    Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp)) {
        Text(
            text = title,
            color = Color.White,
            fontSize = 18.sp,
            fontFamily = GilroyFontFamily,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.padding(bottom = 16.dp)
        )

        // Grid-like layout for players
        val chunkedPlayers = players.chunked(4)
        chunkedPlayers.forEach { rowPlayers ->
            Row(
                modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                rowPlayers.forEach { player ->
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Box(
                            modifier = Modifier
                                .size(60.dp)
                                .clip(CircleShape)
                                .background(Color.Gray.copy(0.2f))
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            player.name,
                            color = Color.White,
                            fontSize = 11.sp,
                            fontFamily = GilroyFontFamily,
                            textAlign = TextAlign.Center
                        )
                    }
                }
                // Fill empty slots if last row has fewer than 4 players
                repeat(4 - rowPlayers.size) {
                    Spacer(modifier = Modifier.size(60.dp))
                }
            }
        }
    }
}

@Composable
fun CommentaryItem(entry: CommentaryEntry) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 24.dp, vertical = 8.dp),
        verticalAlignment = Alignment.Top
    ) {
        Box(
            modifier = Modifier
                .size(32.dp)
                .clip(CircleShape)
                .background(entry.color),
            contentAlignment = Alignment.Center
        ) {
            Text(
                text = entry.ballResult,
                color = Color.White,
                fontSize = 14.sp,
                fontWeight = FontWeight.Bold
            )
        }

        Spacer(modifier = Modifier.width(16.dp))

        Column {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(
                    text = entry.title,
                    color = Color.White,
                    fontSize = 14.sp,
                    fontFamily = GilroyFontFamily,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.weight(1f)
                )
                Text(
                    text = entry.over,
                    color = TextGray,
                    fontSize = 12.sp,
                    fontFamily = GilroyFontFamily
                )
            }
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                text = entry.description,
                color = TextGray,
                fontSize = 12.sp,
                fontFamily = GilroyFontFamily,
                lineHeight = 18.sp
            )
        }
    }
}

