@Composable
fun PlayerInfo(
    name: String,
    score: String,
    detail: String,
    isOnStrike: Boolean,
    isBowler: Boolean = false,
) {
    Column(horizontalAlignment = Alignment.CenterHorizontally) {
        Box {
            Box(
                modifier = Modifier
                    .size(70.dp)
                    .clip(CircleShape)
                    .background(Color.Gray.copy(0.2f))
            )
            if (isOnStrike) {
                Text(
                    text = "",
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .offset(x = 6.dp, y = (-4).dp),
                    fontSize = 18.sp
                )
            }
        }
        Spacer(modifier = Modifier.height(8.dp))
        Text(
            name,
            color = Color.White,
            fontSize = 14.sp,
            fontWeight = FontWeight.Bold,
            fontFamily = GilroyFontFamily
        )
        Row {
            Text(
                score,
                color = Color.White,
                fontSize = 12.sp,
                fontWeight = FontWeight.Bold,
                fontFamily = GilroyFontFamily
            )
            Spacer(modifier = Modifier.width(4.dp))
            Text(detail, color = TextGray, fontSize = 10.sp, fontFamily = GilroyFontFamily)
        }
    }
}

